use std::collections::BTreeMap;

/// Fewest-hop path between two nodes. Ties are broken by neighbour order, which
/// is only stable if the map iterates in a stable order. BTreeMap does.
pub fn shortest(links: &BTreeMap<String, Vec<String>>, from: &str, to: &str) -> Option<Vec<String>> {
    let mut queue = vec![vec![from.to_string()]];
    while let Some(path) = queue.pop() {
        let at = path.last().expect("path is never empty");
        if at == to {
            return Some(path);
        }
        for next in links.get(at)? {
            let mut onward = path.clone();
            onward.push(next.clone());
            queue.push(onward);
        }
    }
    None
}

